import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inp = scanner.nextLine();
        char head = inp.charAt(0);
        String tail = inp.substring(1).replace("dot", ".");
        String combinedStr = head + tail;
        if (combinedStr.endsWith(".")) {
            combinedStr = combinedStr.substring(0, combinedStr.length() - 1) + "dot";
        }
        char headChar = combinedStr.charAt(0);
        String tailPart = combinedStr.substring(1).replaceFirst("at", "@");
        if (tailPart.endsWith("@")) {
            tailPart = tailPart.substring(0, tailPart.length() - 1) + "at";
        }
        System.out.println(headChar + tailPart);
    }
}
